/* eslint-disable max-len */

'use strict';

// MODULES //

var tape = require( 'tape' );
var Float64Array = require( '@stdlib/array/float64' );
var Int32Array = require( '@stdlib/array/int32' );
var dlapmr = require( './../lib/ndarray.js' );


// FIXTURES //

var ROW_MAJOR_FWD = require( './fixtures/row_major_forward.json' );
var ROW_MAJOR_BWD = require( './fixtures/row_major_backward.json' );
var ROW_MAJOR_FWD_LARGE = require( './fixtures/row_major_forward_large.json' );
var ROW_MAJOR_BWD_LARGE = require( './fixtures/row_major_backward_large.json' );
var COL_MAJOR_FWD = require( './fixtures/column_major_forward.json' );
var COL_MAJOR_BWD = require( './fixtures/column_major_backward.json' );
var ROW_MAJOR_FWD_OFFSETS = require( './fixtures/offsets/row_major_forward.json' );
var ROW_MAJOR_BWD_OFFSETS = require( './fixtures/offsets/row_major_backward.json' );
var COL_MAJOR_FWD_OFFSETS = require( './fixtures/offsets/column_major_forward.json' );
var ROW_MAJOR_FWD_LARGE_STRIDES = require( './fixtures/large_strides/row_major_forward.json' );
var ROW_MAJOR_BWD_LARGE_STRIDES = require( './fixtures/large_strides/row_major_backward.json' );
var COL_MAJOR_FWD_LARGE_STRIDES = require( './fixtures/large_strides/column_major_forward.json' );
var ROW_MAJOR_FWD_NEG_STRIDES = require( './fixtures/negative_strides/row_major_forward.json' );
var ROW_MAJOR_BWD_NEG_STRIDES = require( './fixtures/negative_strides/row_major_backward.json' );
var COL_MAJOR_FWD_NEG_STRIDES = require( './fixtures/negative_strides/column_major_forward.json' );
var ROW_MAJOR_FWD_MIXED = require( './fixtures/mixed_strides/row_major_forward.json' );
var ROW_MAJOR_BWD_MIXED = require( './fixtures/mixed_strides/row_major_backward.json' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof dlapmr, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function has an arity of 10', function test( t ) {
	t.strictEqual( dlapmr.length, 10, 'returns expected value' );
	t.end();
});

tape( 'the function returns the matrix unchanged when M is 0', function test( t ) {
	var expected;
	var out;
	var X;
	var K;

	X = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	K = new Int32Array( 0 );
	expected = new Float64Array( [ 1.0, 2.0, 3.0 ] );

	out = dlapmr( true, 0, 3, X, 3, 1, 0, K, 1, 0 );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

tape( 'the function returns the matrix unchanged when M is 1', function test( t ) {
	var expected;
	var out;
	var X;
	var K;

	X = new Float64Array( [ 1.0, 2.0, 3.0 ] );
	K = new Int32Array( [ 0 ] );
	expected = new Float64Array( [ 1.0, 2.0, 3.0 ] );

	out = dlapmr( true, 1, 3, X, 3, 1, 0, K, 1, 0 );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

tape( 'the function applies a forward permutation (row-major)', function test( t ) {
	var expected;
	var data;
	var out;
	var X;
	var K;

	data = ROW_MAJOR_FWD;

	X = new Float64Array( data.X );
	K = new Int32Array( data.K );
	expected = new Float64Array( data.X_out );

	out = dlapmr( data.forwrd, data.M, data.N, X, data.strideX1, data.strideX2, data.offsetX, K, data.strideK, data.offsetK );
	t.strictEqual( out, X, 'returns expected value' );
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

